query:
SELECT p.id AS project_id, p.enterpriseName, p.status, p.industry, p.targetCustomers, JSON_EXTRACT(p.competitorNames, '$') AS competitors, JSON_EXTRACT(p.coreKeywords, '$') AS keywords, p.updatedAt FROM projects p WHERE p.enterpriseName = '海豚知道';
SELECT gs.id AS geo_score_id, gs.projectId, gs.aiVisibilityScore, gs.aiRecommendationScore, gs.competitorWinScore, gs.cognitionAccuracyScore, gs.contentAssetScore, gs.totalScore, gs.visibilityLevel, gs.updatedAt FROM geo_scores gs INNER JOIN projects p ON p.id = gs.projectId WHERE p.enterpriseName = '海豚知道' ORDER BY gs.createdAt DESC LIMIT 1;
SELECT COUNT(*) AS total_questions, SUM(CASE WHEN source IN ('manual','csv') OR questionType = '指定问题' THEN 1 ELSE 0 END) AS specified_questions, SUM(CASE WHEN source = 'ai_generated' THEN 1 ELSE 0 END) AS ai_generated_questions FROM questions q INNER JOIN projects p ON p.id = q.projectId WHERE p.enterpriseName = '海豚知道';
SELECT COUNT(*) AS ai_response_count FROM ai_responses ar INNER JOIN projects p ON p.id = ar.projectId WHERE p.enterpriseName = '海豚知道';
SELECT COUNT(*) AS analysis_count, SUM(CASE WHEN manually_reviewed = 1 THEN 1 ELSE 0 END) AS manually_reviewed_count, SUM(CASE WHEN manual_override_json IS NOT NULL THEN 1 ELSE 0 END) AS manual_override_count FROM analysis_results a INNER JOIN projects p ON p.id = a.projectId WHERE p.enterpriseName = '海豚知道';
SELECT priority, COUNT(*) AS task_count FROM optimization_tasks ot INNER JOIN projects p ON p.id = ot.projectId WHERE p.enterpriseName = '海豚知道' GROUP BY priority ORDER BY priority;
SELECT templateType, COUNT(*) AS template_count, MAX(CHAR_LENGTH(markdownContent)) AS max_length FROM content_templates ct INNER JOIN projects p ON p.id = ct.projectId WHERE p.enterpriseName = '海豚知道' GROUP BY templateType ORDER BY templateType;
SELECT r.id AS report_id, r.totalScore, CHAR_LENGTH(r.markdownContent) AS report_length, r.updatedAt FROM reports r INNER JOIN projects p ON p.id = r.projectId WHERE p.enterpriseName = '海豚知道' ORDER BY r.createdAt DESC LIMIT 1;

